{"code":"def transform(grid):
    # discard the leftmost index column; cyclically start at the row indicated by
    # the first (or main) occurrence of the marker 4 in the upper structure.
    h=len(grid)
    pos=None
    for j,v in enumerate(grid[0]):
        if v==4: pos=j
    if pos is None:
        for i,row in enumerate(grid):
            for j,v in enumerate(row):
                if v==4: pos=j; break
            if pos is not None: break
    s=(pos-1)%h if pos is not None else 0
    rows=[grid[(s+k)%h][1:] for k in range(h)]
    return rows"}

